/**
 * The places a posting names, read off `location` and the reach it reported.
 *
 * `remoteScope` is the posting speaking about itself and so is read first:
 * `worldwide` means the location field is describing where the company sits,
 * not where the candidate must be — the exact over-block that would otherwise
 * close every job at a US-headquartered company that hires globally.
 */
export function namedPlaces(
  text: string | null | undefined,
  remoteScope?: string | null,
): NamedPlaces {
  const scope = (remoteScope ?? "").trim().toLowerCase();
  const raw = (text ?? "").trim();
  const countries: string[] = [];
  const regions: string[] = [];
  let open = scope === "worldwide";

  if (raw) {
    if (!open) open = OPEN_WORDS.some((w) => hasWord(raw, w));
    if (namesUnitedStates(raw)) countries.push("United States");
    for (const [country, aliases] of Object.entries(COUNTRY_ALIASES)) {
      if (countries.includes(country)) continue;
      if (aliases.some((a) => hasWord(raw, a))) countries.push(country);
    }
    for (const c of countriesFromCodes(raw)) {
      if (!countries.includes(c)) countries.push(c);
    }
    for (const [region, aliases] of Object.entries(REGION_ALIASES)) {
      if (aliases.some((a) => hasWord(raw, a))) regions.push(region);
    }
  }

  if (scope === "us_only" && !countries.includes("United States")) {
    countries.push("United States");
  }
  if (scope === "latam" && !regions.includes("latam")) regions.push("latam");

  return { countries, regions, open };
}

/** Does this region cover this country? Unknown region → no. */
export function regionCovers(region: string, country: string): boolean {
  return (REGION_MEMBERS[region] ?? []).includes(country);
}

/**
 * Can a candidate who may work in `workCountries` take a posting that names
 * `places`?
 *
 * Only three answers are possible, and the third is the important one: a
 * posting that names nowhere at all is `"unknown"`, never `"no"`. Naming
 * nothing is the normal state of half the boards we read.
 */
export function reachAllows(
  places: NamedPlaces,
  workCountries: string[],
): "yes" | "no" | "unknown" {
  if (places.open) return "yes";
  if (!workCountries.length) return "unknown";
  if (!places.countries.length && !places.regions.length) return "unknown";
  for (const c of places.countries) {
    if (workCountries.includes(c)) return "yes";
  }
  for (const r of places.regions) {
    if (workCountries.some((c) => regionCovers(r, c))) return "yes";
  }
  return "no";
}

