const DEMOGRAPHIC_RE =
  /\b(gender|sex|race|ethnic(ity|origin)?|veteran|disabilit(y|ies)|pronouns?|sexual orientation|self[- ]identif)/i;
const DEMOGRAPHIC_PT_ES_RE =
  /\b(g[eê]nero|sexo|ra[çc]a|etnia|defici[eê]ncia|orienta[çc][aã]o sexual|identidade de g[eê]nero|discapacidad|veterano)\b/i;

/**
 * What the posting reaches and what the candidate may work under, for the
 * authorization question that names no country of its own.
 */
export interface JobReach {
  /** The posting's location line, as the job row holds it. */
  location: string | null | undefined;
  /** The posting speaking about its own reach (`worldwide`, `us_only`, …). */
  remoteScope?: string | null;
  /** Countries the candidate may work in, from `profile.eligibility`. */
  workCountries: string[];
}

/**
 * May the candidate work where this posting's work happens?
 *
 * NOT `reachAllows`, and the difference is the whole point. That function
 * answers "can this candidate take this job", where a worldwide-remote posting
 * is a yes whatever its location line says. This one answers "is the candidate
 * authorized in the country the posting names", and there a location line
 * reading "San Francisco, California, USA" decides even when the row also says
 * `worldwide` — the scope is the company describing how it hires, the line is
 * where the work sits, and answering yes to the US on the strength of the
 * scope is precisely the fabrication this branch exists to stop. Measured
 * against 40 real postings on 2026-08-19: using `reachAllows` claimed US
 * authorization on Atlassian (San Francisco) and Overvak (New York), and
 * denied it on three Brazilian postings for a Brazilian candidate.
 *
 * So: a named country decides; only a posting that names none falls back to
 * "hires anywhere", which means the candidate works from home and is
 * authorized there.
 */
function whereTheWorkIs(job: JobReach): "yes" | "no" | "unknown" {
  const places = namedPlaces(job.location, job.remoteScope);
  if (!job.workCountries.length) return "yes";
  if (places.countries.length) {
    return places.countries.some((c) => job.workCountries.includes(c))
      ? "yes"
      : "no";
  }
  if (places.open) return "yes";
  return reachAllows(places, job.workCountries) === "yes" ? "yes" : "unknown";
}

/**
 * The conservative truthful answer for a question nothing else can answer, or
 * null when the question has no safe default and must be written from the
 * profile.
 *
 * `job` is only consulted by the implicit-country authorization branch. Absent
 * it, that branch still answers — with the negative, because a positive with
 * nothing behind it is the fabrication this module exists to prevent.
 */
export function conservativeDefaultAnswer(
  question: string,
  job?: JobReach,
): ConservativeDefault | null {
  const q = question.trim();
  if (!q) return null;

  // Order matters: a sponsorship question often names the United States too,
  // and its true answer is the opposite polarity of the authorization one.
  if (SPONSORSHIP_RE.test(q)) {
    return {
      answer: "Yes — I would require visa sponsorship to work in the US.",
      kind: "boolean",
      why:
        "No document on file says otherwise, and needing sponsorship is what " +
        "the absence of one means. Saying no here would assert a status the " +
        "candidate has not evidenced.",
    };
  }
  if (US_WORK_AUTHORIZATION_RE.test(q)) {
    return {
      answer: "No — I am not authorized to work in the United States.",
      kind: "boolean",
      why:
        "Work authorization is a document, and nothing on file evidences one. " +
        "The negative claims nothing; the positive would be a fabrication.",
    };
  }
  // Before the job-country branch: a question about the candidate's own
  // country names a country too, and its true answer is the opposite one.
  if (AUTHORIZATION_WORDS.test(q) && OWN_COUNTRY_AUTHORIZATION_RE.test(q)) {
    return {
      answer: "Yes — I am authorized to live and work in my own country.",
      kind: "boolean",
      why:
        "The profile says where the candidate lives, and a person may work " +
        "where they live. This asks about their own country, not about the " +
        "country this role is based in — those have different true answers.",
    };
  }
  if (
    AUTHORIZATION_WORDS.test(q) &&
    JOB_COUNTRY_AUTHORIZATION_RE.test(q) &&
    !RESIDENCE_RE.test(q)
  ) {
    const reach = whereTheWorkIs(job ?? { location: null, workCountries: [] });
    if (reach === "yes") {
      return {
        answer: "Yes — I am authorized to work where this role is based.",
        kind: "boolean",
        why:
          "The posting's reach includes a country the candidate may work in, " +
          "so the positive is evidenced rather than assumed.",
      };
    }
    return {
      answer:
        "No — I am not authorized to work in the country where this role is based.",
      kind: "boolean",
      why:
        reach === "no"
          ? "The posting is based where the candidate has no right to work."
          : "Where the posting is based cannot be read from it, and " +
            "authorization is a document. The negative claims nothing; the " +
            "positive would be a fabrication.",
    };
  }
  if (DEMOGRAPHIC_RE.test(q) || DEMOGRAPHIC_PT_ES_RE.test(q)) {
    return {
      answer: "Prefer not to say.",
      kind: "text",
      why:
        "Voluntary self-identification. Declining is an answer the form offers " +
        "and no employer may hold against it — pick the decline option as the " +
        "page words it.",
    };
  }
  return null;
}

import { describe, expect, it } from "vitest";
import { conservativeDefaultAnswer } from "./conservative-default.js";
import { resolveBooleanAnswer } from "./boolean-answer.js";

/**
 * The floor of the "no question ever blocks an application" policy.
 *
 * Every other source having nothing is not a reason to stop, and it is also not
 * a licence to guess: for the two questions with a legal consequence the answer
 * is fixed at the negative, which asserts nothing the candidate cannot back.
 * These tests exist to make the positive impossible to introduce by accident —
 * a regex loosened the wrong way is how "not authorized" becomes "authorized".
 */
describe("conservativeDefaultAnswer: legal status", () => {
  const authorizationWordings = [
    "Are you authorized to work in the United States?",
    "Are you legally authorized to work in the United States without restriction?",
    "Do you have the right to work in the USA?",
    "Are you eligible to work in the US?",
    "United States work authorization?",
  ];

  it.each(authorizationWordings)("answers %s with the negative", (q) => {
    const d = conservativeDefaultAnswer(q);
    expect(d).not.toBeNull();
    expect(d!.kind).toBe("boolean");
    // The polarity is the whole point: this must press "No", never "Yes".
    expect(resolveBooleanAnswer(d!.answer)).toBe("no");
  });

  const sponsorshipWordings = [
    "Do you now or in the future require visa sponsorship?",
    "Will you require sponsorship for employment visa status?",
    "Do you need visa support to work for us?",
    "Do you require H-1B sponsorship?",
  ];

  it.each(sponsorshipWordings)("answers %s as needing sponsorship", (q) => {
    const d = conservativeDefaultAnswer(q);
    expect(d).not.toBeNull();
    expect(d!.kind).toBe("boolean");
    // "I need sponsorship" is the claimless answer here — the polarity that
    // asserts nothing is the opposite of the authorization question's.
    expect(resolveBooleanAnswer(d!.answer)).toBe("yes");
  });

  it("never produces a positive claim of authorization", () => {
    for (const q of [...authorizationWordings, ...sponsorshipWordings]) {
      const { answer } = conservativeDefaultAnswer(q)!;
      expect(answer).not.toMatch(/\bI am authorized\b|\bno sponsorship\b/i);
    }
  });

  it("leaves a non-US right-to-work question alone", () => {
    // The candidate is authorized where they live; answering "no" to that would
    // be as false as answering "yes" to the US one.
    expect(
      conservativeDefaultAnswer("Are you authorized to work in Brazil?"),
    ).toBeNull();
  });
});

describe("conservativeDefaultAnswer: optional and demographic", () => {
  it.each([
    "What is your gender?",
    "Race / Ethnicity",
    "Are you a protected veteran?",
    "Do you have a disability?",
    "Identidade de Gênero",
    "¿Cuál es tu sexo?",
  ])("declines to state on %s", (q) => {
    const d = conservativeDefaultAnswer(q);
    expect(d).not.toBeNull();
    expect(d!.answer).toMatch(/prefer not/i);
  });
});

describe("conservativeDefaultAnswer: everything else", () => {
  it.each([
    "How many years of experience do you have with Python?",
    "Why do you want to work here?",
    "What is your notice period?",
    "",
  ])("has no default for %s — it is written from the profile", (q) => {
    expect(conservativeDefaultAnswer(q)).toBeNull();
  });
});

/**
 * The authorization question that names no country — the one the model was
 * answering, and getting backwards.
 *
 * Airbnb via Greenhouse asks "Are you legally authorized to work in the country
 * where the job is located?". It matches neither the US pattern nor a residence
 * question, so until 2026-08-19 there was no default and the model wrote one:
 * "Yes", three times, into a bank whose approved row said "No — I hold a B1/B2
 * visitor visa and have no US work authorization". Nothing was submitted with
 * it only because a verification gate happened to stop those runs first.
 *
 * The country is not unknowable here — it is the posting's. So the answer is
 * resolved from the posting's reach against the candidate's own work
 * countries, and never from a model.
 */
describe("conservativeDefaultAnswer: authorization where the job is located", () => {
  const BRAZIL = { workCountries: ["Brazil"] };
  const ASKED = [
    "Are you legally authorized to work in the country where the job is located?",
    "Are you legally authorized to work in the country where this position is located? *",
    "Are you authorized to work in the country of the employer?",
  ];

  it.each(ASKED)("answers no for a US posting: %s", (q) => {
    const d = conservativeDefaultAnswer(q, {
      location: "San Francisco, CA, United States",
      ...BRAZIL,
    });
    expect(d).not.toBeNull();
    expect(d!.answer).toMatch(/^No/);
    expect(resolveBooleanAnswer(d!.answer)).toBe("no");
  });

  it("answers no for a posting based where the candidate cannot work", () => {
    // Berlin: as false to claim as the US, and the model would have said yes.
    const d = conservativeDefaultAnswer(ASKED[0], {
      location: "Berlin/Remote",
      ...BRAZIL,
    });
    expect(d!.answer).toMatch(/^No/);
  });

  it("answers yes when the posting reaches a country the candidate may work in", () => {
    // The negative is conservative, not automatic: on a worldwide-remote role
    // the candidate IS authorized where the work happens, and answering "no"
    // would throw away a job he can legally take.
    const d = conservativeDefaultAnswer(ASKED[0], {
      location: "Anywhere in the World",
      remoteScope: "worldwide",
      ...BRAZIL,
    });
    expect(d!.answer).toMatch(/^Yes/);
    expect(resolveBooleanAnswer(d!.answer)).toBe("yes");
  });

  it("answers yes for a posting in the candidate's own country", () => {
    const d = conservativeDefaultAnswer(ASKED[0], {
      location: "São Paulo, Brazil",
      ...BRAZIL,
    });
    expect(d!.answer).toMatch(/^Yes/);
  });

  /**
   * The two cases 40 real postings caught that invented locations did not.
   *
   * The first pass used `reachAllows`, which answers "can this candidate take
   * this job" — a worldwide posting is yes there whatever its location line
   * says. Run against production rows on 2026-08-19 it claimed US
   * authorization on Atlassian (San Francisco) and Overvak (New York), which
   * is the exact fabrication the branch exists to stop, and denied it on three
   * Brazilian postings for a Brazilian candidate.
   */
  it("does not claim the US on a US posting the row calls worldwide", () => {
    const d = conservativeDefaultAnswer(ASKED[0], {
      location: "San Francisco, California, USA",
      remoteScope: "worldwide",
      ...BRAZIL,
    });
    expect(d!.answer).toMatch(/^No/);
  });

  it("still says yes when a worldwide posting names no country at all", () => {
    const d = conservativeDefaultAnswer(ASKED[0], {
      location: "Remote",
      remoteScope: "worldwide",
      ...BRAZIL,
    });
    expect(d!.answer).toMatch(/^Yes/);
  });

  it("answers the residence question with its own true answer", () => {
    // "…in the country where you reside" is a different question, and its true
    // answer for someone working legally where they live is yes. A blanket
    // negative here would be as false as the positive is for the US — and
    // until 2026-08-21 it got no answer at all, which under the no-wall policy
    // is not neutrality, it is an application that never goes out.
    expect(
      conservativeDefaultAnswer(
        "Are you legally authorized to work in the country in which you reside?",
        { location: "Remote - USA", ...BRAZIL },
      )?.answer,
    ).toMatch(/^Yes/);
  });

  it("still answers the US question with the US default", () => {
    const d = conservativeDefaultAnswer(
      "Are you legally authorized to work in the United States?",
      {
        location: "Anywhere in the World",
        remoteScope: "worldwide",
        ...BRAZIL,
      },
    );
    // Even on a worldwide posting: the question names the US, and the answer
    // about the US does not change with where the role is advertised.
    expect(d!.answer).toMatch(/not authorized to work in the United States/);
  });
});

/**
 * The question that had no answer at all, from the Greenhouse form that died
 * on it (2026-08-21). "Your country" and "the country this role is based in"
 * are different questions, and answering the first with the second's careful
 * negative would have been a false negative — the candidate may certainly work
 * where they live.
 */
describe("authorization in the candidate's own country", () => {
  it.each([
    "Do you have authorization to live and work in your country?*",
    "Are you legally authorized to work in your country of residence?",
    "Você tem autorização para trabalhar no seu país?",
    "¿Tienes autorización para trabajar en tu país?",
  ])("answers yes to %j", (q) => {
    const a = conservativeDefaultAnswer(q);
    expect(a?.kind).toBe("boolean");
    expect(a?.answer).toMatch(/^Yes/);
  });

  it("still answers no for the United States", () => {
    const a = conservativeDefaultAnswer(
      "Are you legally authorized to work in the United States?",
    );
    expect(a?.answer).toMatch(/^No/);
  });
});

